// Estado compartido por UART-RVC e I2C; en I2C, sondear lee el bus en lugar del puerto serie.
struct RbImuRvc {
    Stream* stream = nullptr;
    void (*sondear)() = nullptr;
    uint8_t datos[17];
    uint8_t largo = 0, cabecera = 0;
    bool listo = false, tiene_anterior = false;
    float yaw = 0, pitch = 0, roll = 0, ax = 0, ay = 0, az = 0, cero = 0, anterior = 0, acumulado = 0;
    uint32_t inicio = 0, ultimo = 0;
};
static RbImuRvc imu_rvc;
inline void imu_rvc_configurar(Stream& stream) {
    imu_rvc.stream = &stream; imu_rvc.sondear = nullptr; imu_rvc.largo = 0; imu_rvc.cabecera = 0; imu_rvc.listo = false;
    imu_rvc.cero = 0; imu_rvc.acumulado = 0; imu_rvc.tiene_anterior = false;
    imu_rvc.inicio = millis();
}
inline int16_t imu_rvc_valor(uint8_t i) {
    return int16_t(uint16_t(imu_rvc.datos[1 + 2 * i]) | uint16_t(imu_rvc.datos[2 + 2 * i]) << 8);
}
inline void imu_rvc_acumular(float yaw) {
    if (!isfinite(yaw)) return;
    if (imu_rvc.tiene_anterior) {
        float delta = imu_rvc.anterior - yaw + 180;
        delta = delta - 360 * floorf(delta / 360) - 180;
        if (fabsf(delta) <= 90) imu_rvc.acumulado += delta;
    }
    imu_rvc.anterior = yaw; imu_rvc.tiene_anterior = true;
}
// Paquete RVC de 19 bytes a 115200: 0xAA 0xAA, índice, yaw, pitch, roll (0.01°), aceleración x/y/z (mg), 3 bytes y suma.
inline void imu_rvc_leer() {
    if (imu_rvc.sondear) { imu_rvc.sondear(); return; }
    if (!imu_rvc.stream) return;
    uint32_t ahora = millis();
    for (int n = imu_rvc.stream->available(); n > 0; n--) {
        int c = imu_rvc.stream->read();
        if (c < 0) break;
        uint8_t b = uint8_t(c);
        if (imu_rvc.cabecera < 2) { imu_rvc.cabecera = b == 0xAA ? imu_rvc.cabecera + 1 : 0; imu_rvc.largo = 0; continue; }
        imu_rvc.datos[imu_rvc.largo++] = b;
        if (imu_rvc.largo < 17) continue;
        imu_rvc.cabecera = 0; imu_rvc.largo = 0;
        uint8_t suma = 0;
        for (uint8_t i = 0; i < 16; i++) suma += imu_rvc.datos[i];
        if (suma != imu_rvc.datos[16]) continue;
        imu_rvc.yaw = imu_rvc_valor(0) * 0.01f; imu_rvc.pitch = imu_rvc_valor(1) * 0.01f; imu_rvc.roll = imu_rvc_valor(2) * 0.01f;
        imu_rvc_acumular(imu_rvc.yaw);
        imu_rvc.ax = imu_rvc_valor(3) * 0.00980665f; imu_rvc.ay = imu_rvc_valor(4) * 0.00980665f; imu_rvc.az = imu_rvc_valor(5) * 0.00980665f;
        imu_rvc.listo = true; imu_rvc.ultimo = ahora;
    }
}
inline bool imu_rvc_esperar(const char* bloque) {
    if (rb_failed) return true;
    imu_rvc_leer();
    if (imu_rvc.listo) return true;
    if (uint32_t(millis() - imu_rvc.inicio) < 1000) return false;
    rb_fail(bloque, "No llegan datos del BNO085: PS0 a 3.3 V (modo RVC) y TX del sensor a RX");
    return true;
}
inline bool imu_rvc_dato(const char* bloque) {
    imu_rvc_leer();
    if (!imu_rvc.listo) { rb_fail(bloque, "Configura la IMU BNO085 al iniciar y espera a que termine"); return false; }
    if (uint32_t(millis() - imu_rvc.ultimo) > 500) { rb_fail(bloque, imu_rvc.sondear ? "El BNO085 dejo de enviar datos: revisa SDA y SCL" : "El BNO085 dejo de enviar datos: revisa el cable TX"); return false; }
    return true;
}
// El yaw RVC crece hacia la izquierda; se invierte para que, como en la BNO055, girar a la derecha sea positivo.
inline float imu_rvc_giro(const char* bloque) {
    if (!imu_rvc_dato(bloque)) return 0;
    float d = imu_rvc.cero - imu_rvc.yaw + 180;
    return roundf((d - 360 * floorf(d / 360) - 180) * 10) / 10;
}
inline void imu_rvc_reiniciar(const char* bloque) {
    if (imu_rvc_dato(bloque)) { imu_rvc.cero = imu_rvc.yaw; imu_rvc.acumulado = 0; }
}
inline float imu_rvc_inclinacion(const String& eje, const char* bloque) {
    if (!imu_rvc_dato(bloque)) return 0;
    return eje[0] == '2' ? imu_rvc.pitch : imu_rvc.roll;
}
inline float imu_rvc_aceleracion(const String& eje, const char* bloque) {
    if (!imu_rvc_dato(bloque)) return 0;
    return eje[0] == 'x' ? imu_rvc.ax : eje[0] == 'y' ? imu_rvc.ay : imu_rvc.az;
}
inline float imu_rvc_giro_acumulado(const char* bloque) {
    if (!imu_rvc_dato(bloque)) return 0;
    return roundf(imu_rvc.acumulado * 10) / 10;
}

