    return eje[0] == 'x' ? imu_rvc.ax : eje[0] == 'y' ? imu_rvc.ay : imu_rvc.az;
}
inline float imu_rvc_giro_acumulado(const char* bloque) {
    if (!imu_rvc_dato(bloque)) return 0;
    return roundf(imu_rvc.acumulado * 10) / 10;
}
